/// Durations in seconds and the matching curves. Under Reduce Motion, animations are nil and changes are instant.
public enum PerpetoMotion {
    public static let fast: Double = 0.14
    public static let base: Double = 0.22
    public static let slow: Double = 0.36
    public static func duration(_ value: Double, reduceMotion: Bool) -> Double { reduceMotion ? 0 : value }

    /// Matches --ease-out: for anything appearing, expanding or moving into place.
    public static func easeOut(_ duration: Double = base, reduceMotion: Bool = false) -> Animation? {
        reduceMotion ? nil : .timingCurve(0.16, 1, 0.3, 1, duration: duration)
    }

    /// Matches --ease-standard: for hover, press and state changes.
    public static func standard(_ duration: Double = fast, reduceMotion: Bool = false) -> Animation? {
        reduceMotion ? nil : .timingCurve(0.2, 0, 0, 1, duration: duration)
    }
}

/// System sans for interface and display, system monospace for identifiers only.
public enum PerpetoType {
    public static let text12: CGFloat = 12
    public static let text13: CGFloat = 13
    public static let text14: CGFloat = 14
    public static let text16: CGFloat = 16
    public static let text20: CGFloat = 20
    public static let text24: CGFloat = 24
    public static let text28: CGFloat = 28
    public static let text32: CGFloat = 32

    public static let display40: CGFloat = 40
    public static let display48: CGFloat = 48
    public static let display56: CGFloat = 56
    public static let display64: CGFloat = 64
    public static let display72: CGFloat = 72

    public static let bodyLineHeight: CGFloat = 1.5
    public static let headingLineHeight: CGFloat = 1.2
    public static let displayLineHeight: CGFloat = 1.05
    /// Tracking as a fraction of the font size. Negative: large type is tight, never tracked out.
    public static let headingTracking: CGFloat = -0.015
    public static let displayTracking: CGFloat = -0.03

    /// Interface text, regular or medium. Sizes: 12, 13, 14, 16, 20, 24, 28, 32.
    public static func text(_ size: CGFloat, weight: Font.Weight = .regular) -> Font {
        .system(size: size, weight: weight)
    }

    /// Semibold, sentence-case titles for page headers and sections. Sizes 20 to 32.
    public static func title(_ size: CGFloat = text28) -> Font {
        .system(size: size, weight: .semibold)
    }

    /// Semibold, sentence-case display type. Sizes: 40, 48, 56, 64, 72.
    public static func display(_ size: CGFloat = display40) -> Font {
        .system(size: size, weight: .semibold)
    }

    /// Monospace for identifiers: run IDs, paths, branches, commit hashes and model IDs.
    public static func mono(_ size: CGFloat = text13, weight: Font.Weight = .regular) -> Font {
        .system(size: size, weight: weight, design: .monospaced)
    }

    /// Points of tracking for a title or display size, for `.tracking(_:)`.
    public static func tracking(forDisplay size: CGFloat) -> CGFloat { size * displayTracking }
    public static func tracking(forHeading size: CGFloat) -> CGFloat { size * headingTracking }

    /// Extra line spacing that brings the system font's default (about 1.2) up to a target line height.
    public static func lineSpacing(for size: CGFloat, lineHeight: CGFloat = bodyLineHeight) -> CGFloat {
        max(0, size * (lineHeight - 1.2))
    }
}

private struct PerpetoShadowLayers: ViewModifier {
    let layers: [PerpetoElevation.Layer]

    func body(content: Content) -> some View {
        layers.reduce(AnyView(content)) { view, layer in
            AnyView(view.shadow(color: layer.color, radius: layer.radius, x: layer.x, y: layer.y))
        }
    }
}

public extension View {
    /// Body copy: system sans at the Perpeto Mono line height.
    func perpetoBody(_ size: CGFloat = PerpetoType.text14, color: Color = PerpetoColor.ink) -> some View {
        font(PerpetoType.text(size))
            .lineSpacing(PerpetoType.lineSpacing(for: size))
            .foregroundStyle(color)
    }

    /// Page or section title: semibold, slightly tight, sentence case.
    func perpetoTitle(_ size: CGFloat = PerpetoType.text28) -> some View {
        font(PerpetoType.title(size))
            .tracking(PerpetoType.tracking(forHeading: size))
            .foregroundStyle(PerpetoColor.ink)
    }

    /// Display headline: semibold, tight, sentence case.
    func perpetoDisplay(_ size: CGFloat = PerpetoType.display40) -> some View {
        font(PerpetoType.display(size))
            .tracking(PerpetoType.tracking(forDisplay: size))
            .foregroundStyle(PerpetoColor.ink)
    }

    /// Soft elevation with its hairline ring, for a shape with the given corner radius.
    func perpetoElevation(_ elevation: PerpetoElevation, cornerRadius: CGFloat = PerpetoRadius.panel) -> some View {
        overlay {
            if let ring = elevation.ring {
                RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
                    .strokeBorder(ring, lineWidth: PerpetoStroke.hairline)
            }
        }
        .modifier(PerpetoShadowLayers(layers: elevation.layers))
    }

    /// White card on the canvas: generous padding, 20 pt continuous corners, soft card elevation, no border.
    func perpetoCard(padding: CGFloat = PerpetoLayout.cardPadding, cornerRadius: CGFloat = PerpetoRadius.panel) -> some View {
        self.padding(padding)
            .background(PerpetoColor.surface, in: RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
            .perpetoElevation(.card, cornerRadius: cornerRadius)
    }
}
